"""Bind an exact school crossing-zone case to reviewed original source bytes."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from school_uturn import CASES, SOURCES, construct as construct_school, validate_scene


ASSIGNMENT = "testing__C255863__NRS-484B-363-3__motor_vehicle_driver"
ROOT = Path(__file__).resolve().parent


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def load_case(case_id):
    if not case_id.startswith(ASSIGNMENT + "__"):
        raise ValueError("exact school-zone case ID required")
    name = case_id[len(ASSIGNMENT) + 2:]
    for case in CASES:
        if case.name == name:
            return case
    raise ValueError("unknown exact school-zone case")


def validate_site(path, case_id):
    path = Path(path).resolve()
    site = json.loads(path.read_text())
    case = load_case(case_id)
    if site.get("case_id") != case_id or site.get("map_sha256") is None:
        raise ValueError("reviewed exact school-zone site/map missing")
    records = site.get("source_records")
    if not isinstance(records, dict) or set(records) != set(SOURCES):
        raise ValueError("reviewed school-zone source inventory incomplete")
    for name in SOURCES:
        record = records[name]
        source = (path.parent / record["path"]).resolve()
        if path.parent not in source.parents or not source.is_file():
            raise ValueError("reviewed source outside packet: " + name)
        digest = sha(source)
        if digest != record.get("sha256") or digest != site.get(name + "_source_sha256"):
            raise ValueError("reviewed source hash differs: " + name)
    timing = site.get("timing_packet", {})
    timing_sources = {
        "calendar_source_sha256": "school_calendar",
        "operation_schedule_source_sha256": "school_operation_time",
        "class_schedule_source_sha256": "class_hours",
        "local_clock_source_sha256": "local_clock",
        "beacon_configuration_source_sha256": "beacon_configuration",
        "beacon_state_source_sha256": "beacon_state",
        "sign_instruction_source_sha256": "sign_instruction",
    }
    for field, name in timing_sources.items():
        if timing.get(field) != records[name]["sha256"]:
            raise ValueError("school timing source hash differs: " + name)
    validate_scene(site, case)
    site["_source_sha256"] = sha(path)
    return site


def construct(adapter, site_path, case_id):
    site = validate_site(site_path, case_id)
    return construct_school(adapter, site, load_case(case_id))

"""Source-bound clock and beacon facts for the school-zone U-turn exceptions."""

from __future__ import annotations

from datetime import datetime, timedelta


def _instant(value, name):
    if not isinstance(value, str):
        raise ValueError("source-bound " + name + " timestamp required")
    try:
        parsed = datetime.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("valid " + name + " timestamp required") from exc
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError("offset-aware " + name + " timestamp required")
    return parsed


def derive(packet: dict) -> dict:
    if not isinstance(packet, dict) or packet.get("source_kind") != "original_school_schedule_and_device_readback":
        raise ValueError("original school schedule and device readback required")
    required_hashes = ("calendar_source_sha256", "operation_schedule_source_sha256",
                       "class_schedule_source_sha256", "local_clock_source_sha256",
                       "beacon_configuration_source_sha256", "beacon_state_source_sha256",
                       "sign_instruction_source_sha256")
    for name in required_hashes:
        value = packet.get(name)
        if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
            raise ValueError("independent source hash required: " + name)
    now = _instant(packet.get("local_datetime"), "local clock")
    end = _instant(packet.get("last_operation_end"), "last operation end")
    next_start = _instant(packet.get("next_operation_start"), "next operation start")
    class_start = _instant(packet.get("class_start"), "class start")
    class_end = _instant(packet.get("class_end"), "class end")
    if not end < next_start or not class_start < class_end:
        raise ValueError("source schedule ordering invalid")
    for name in ("school_in_session", "beacon_operational", "beacon_flashing",
                 "sign_limit_active"):
        if not isinstance(packet.get(name), bool):
            raise ValueError("original school/device state required: " + name)
    lights = packet.get("beacon_yellow_light_count")
    if type(lights) is not int or lights < 0:
        raise ValueError("original beacon light count required")
    alternating = packet.get("beacon_alternating_flash_capable")
    if not isinstance(alternating, bool):
        raise ValueError("original alternating flash capability required")
    if packet["beacon_operational"] and (lights < 2 or not alternating):
        raise ValueError("operational speed limit beacon definition not demonstrated")
    if packet["beacon_flashing"] and not packet["beacon_operational"]:
        raise ValueError("nonoperational beacon cannot be recorded flashing")
    outside_half_hour = end + timedelta(minutes=30) <= now <= next_start - timedelta(minutes=30)
    return {"school_session": packet["school_in_session"],
            "operation_window": not outside_half_hour,
            "outside_half_hour": outside_half_hour,
            "during_class": class_start <= now <= class_end,
            "beacon_operational": packet["beacon_operational"],
            "beacon_flashing": packet["beacon_flashing"],
            "sign_limit_active": packet["sign_limit_active"],
            "source_limit": "Clock arithmetic and device facts do not resolve undefined legal boundary treatment or U-turn legality."}

"""Independent original-source audit for six cases and five comparisons."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path

from comparison_audit import audit as compare
from saved_finalizer import finalize
from school_scene_construction import ASSIGNMENT


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def audit(index_path: Path) -> dict:
    index_path = Path(index_path)
    index = json.loads(index_path.read_text())
    plan = json.loads((Path(__file__).resolve().parent / "case-plan.json").read_text())
    if index.get("assignment_id") != ASSIGNMENT or index.get("source_kind") != "original_native_delivery":
        raise ValueError("original delivery index identity/source mismatch")
    cases = index.get("cases")
    expected = {case["case_id"] for case in plan["cases"]}
    if not isinstance(cases, dict) or set(cases) != expected:
        raise ValueError("exact six original delivery cases required")
    packets = {}
    for case_id, names in cases.items():
        if not isinstance(names, dict) or set(names) != {"context", "trace", "receipt", "camera_manifest", "measurement", "comparison_packet"}:
            raise ValueError("original delivery source inventory incomplete: " + case_id)
        paths = {}
        for key, item in names.items():
            if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
                raise ValueError("original delivery source binding missing: " + case_id)
            relative = Path(item["path"])
            if relative.is_absolute() or ".." in relative.parts:
                raise ValueError("original delivery source path escapes index")
            origin = index_path.parent.resolve()
            unresolved = origin / relative
            path = unresolved.resolve()
            if (origin not in path.parents or unresolved.is_symlink() or
                    not path.is_file() or sha(path) != item["sha256"]):
                raise ValueError("original delivery source changed: " + case_id + ": " + key)
            paths[key] = path
        measured = finalize(case_id, paths["context"], paths["trace"], paths["receipt"],
                            paths["camera_manifest"])
        saved = json.loads(paths["measurement"].read_text())
        if saved != measured or saved.get("statutory_disposition") != "unresolved_pending_source_review":
            raise ValueError("saved original measurement differs or overclaims: " + case_id)
        packets[case_id] = paths
    comparisons = {}
    for row in plan["comparisons"]:
        left, right = row["case_ids"]
        packet = lambda key: {"case_id": key, "context": str(packets[key]["context"]),
                              "trace": str(packets[key]["trace"]),
                              "receipt": str(packets[key]["receipt"])}
        comparisons[row["comparison_id"]] = compare(packets[left]["comparison_packet"], packets[right]["comparison_packet"], row["comparison_id"])
    return {"assignment_id": ASSIGNMENT, "source_kind": "original_native_delivery",
            "case_count": len(packets), "comparison_count": len(comparisons),
            "index_sha256": sha(index_path), "legal_judgment": "unresolved",
            "physical_acceptance": "unverified",
            "comparisons": comparisons}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--index", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    args.output.write_text(json.dumps(audit(args.index), sort_keys=True, indent=2) + "\n")


if __name__ == "__main__":
    main()
